      "id": "b2-dunst",
      "layout": "standardStudy",
      "translation": "pára • gőz • köd",
      "explanation": [
        "A lényeg: a der Dunst hímnemű főnév (a magyarban nincs nyelvtani nem, ezért a der névelővel együtt tanuld), jelentése pára, ködös levegő, kigőzölgés: enyhe pára, amely homályossá teszi a levegőt, vagy szag és kipárolgás.",
        "A többes szám die Dünste (umlauttal), ritkán használják, főként kigőzölgésekre: giftige Dünste. Egyes számban a der Dunst gyakran a város, tó vagy völgy fölötti párára utal.",
        "A keinen blassen Dunst von etwas haben kifejezés azt jelenti, hogy valakinek halvány fogalma sincs valamiről."
      ],
      "examples": [
        {
          "de": "Über dem See lag ein feiner Dunst.",
          "lv": "A tó fölött finom pára ült."
        },
        {
          "de": "In der Küche hing der Dunst von gebratenem Fleisch.",
          "lv": "A konyhában sült hús gőze terjengett."
        },
        {
          "de": "Giftige Dünste stiegen aus dem Fass auf.",
          "lv": "Mérgező kigőzölgések szálltak fel a hordóból."
        },
        {
          "de": "Ich habe keinen blassen Dunst davon.",
          "lv": "Halvány fogalmam sincs róla."
        }
      ],
      "comparison": [
        {
          "word": "der Nebel",
          "meaning": "köd",
          "example": "Im Herbst gibt es oft Nebel. – Ősszel gyakran van köd."
        },
        {
          "word": "der Dampf",
          "meaning": "gőz (forró)",
          "example": "Dampf steigt aus dem Topf auf. – Gőz száll fel a fazékból."
        },
        {
          "word": "der Rauch",
          "meaning": "füst",
          "example": "Rauch steigt aus dem Schornstein auf. – Füst száll fel a kéményből."
        }
      ],
      "tip": [
        "A Dunst szót akkor használd, ha párás a levegő, vagy szagos kigőzölgésről van szó; sűrű ködre a Nebel szót mondják.",
        "A keinen blassen Dunst haben kifejezés köznyelvi; kötetlen beszédben használd."
      ],
      "important": [
        "A der Dunst nem ugyanaz, mint a Dampf: a Dampf forró gőz, a Dunst enyhe pára vagy kigőzölgés.",
        "A die Dünste többes szám umlautos, és ritkán használják."
      ],
