        "Elváló igekötő: ich schleiche mich ein, schlich mich ein, habe mich eingeschlichen. A hely, ahová valaki besurran, in + Akkusativ (tárgyeset) szerkezettel áll (in das Haus, ins Haus). A Perfekt haben segédigével képződik, mivel az ige visszaható."
