        "Általában Genitiv (birtokos eset) követi (sich seiner entsinnen, sich der Worte entsinnen), ma már an + Akkusativ is. Gyakori fordulat: Soviel ich mich entsinne, … — amennyire emlékszem. Alakok: entsinnt sich, entsann sich, hat sich entsonnen."
